{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/src/mhd && python3 - <<'EOF'
p='helio.cu'
s=open(p).read()
s=s.replace('''__global__ void k_bc_inner(float* __restrict__ U, const float* __restrict__ M, int nlat, int nlon, float lat0, float dlat, float lon0, float dlon, int m0, float w, float lonshift, float tau, float bscale, const float* __restrict__ rc, const float* __restrict__ tc, const float* __restrict__ pc)
{''','''__global__ void k_bc_inner(float* __restrict__ U, const float* __restrict__ M, int nlat, int nlon, float lat0, float dlat, float lon0, float dlon, int m0, float w, float lonshift, float tau, float bscale, const float* __restrict__ rc, const float* __restrict__ tc, const float* __restrict__ pc, int fluxform)
{''')
s=s.replace('''    bnd_sample(M, nlat, nlon, lat0, dlat, lon0, dlon, m0, w, lat, lon, o);
    o[3] *= bscale;
    cme_override(tau, th, ph, o);''','''    bnd_sample(M, nlat, nlon, lat0, dlat, lon0, dlon, m0, w, lat, lon, o);
    if (fluxform) {
        float vv = fmaxf(o[0], 50.f);
        o[1] = o[1] / (vv * vv);
        o[2] = o[2] / o[1];
    }
    o[3] *= bscale;
    cme_override(tau, th, ph, o);''')
s=s.replace('''__global__ void k_init(float* __restrict__ U, const float* __restrict__ M, int nlat, int nlon, float lat0, float dlat, float lon0, float dlon, int m0, float w, float lonshift, float bscale, const float* __restrict__ rc, const float* __restrict__ tc, const float* __restrict__ pc)
{''','''__global__ void k_init(float* __restrict__ U, const float* __restrict__ M, int nlat, int nlon, float lat0, float dlat, float lon0, float dlon, int m0, float w, float lonshift, float bscale, const float* __restrict__ rc, const float* __restrict__ tc, const float* __restrict__ pc, int fluxform)
{''')
s=s.replace('''    bnd_sample(M, nlat, nlon, lat0, dlat, lon0, dlon, m0, w, 90.f - th * 57.29577951f, ph * 57.29577951f - lonshift, o);
    o[3] *= bscale;
    float u[NV];''','''    bnd_sample(M, nlat, nlon, lat0, dlat, lon0, dlon, m0, w, 90.f - th * 57.29577951f, ph * 57.29577951f - lonshift, o);
    if (fluxform) {
        float vv = fmaxf(o[0], 50.f);
        o[1] = o[1] / (vv * vv);
        o[2] = o[2] / o[1];
    }
    o[3] *= bscale;
    float u[NV];''')
s=s.replace('''lonshift(ts), (float)ta, (float)bscale, d_rc, d_tc, d_pc);''','''lonshift(ts), (float)ta, (float)bscale, d_rc, d_tc, d_pc, fluxform);''')
s=s.replace('''lonshift(t_start), (float)bscale, d_rc, d_tc, d_pc);''','''lonshift(t_start), (float)bscale, d_rc, d_tc, d_pc, fluxform);''')
s=s.replace('''    int inner_mode = (int)dget("inner_mode", 0),''','''    int fluxform = (int)dget("bnd_fluxform", 0);
    int inner_mode = (int)dget("inner_mode", 0),''')
open(p,'w').write(s)
EOF
grep -c "fluxform" helio.cu; make helio helio_trace 2>&1 | grep -i -E "error"; ls -la helio helio_trace | awk '{print $6,$7,$8}'",
  "description": "Add flux-form boundary interpolation option",
  "timeout": 600000
}

